    "id": "sathva-post-18568596574006894",
    "title": "INTERNATIONAL WOMEN’S DAY👭",
    "caption": "INTERNATIONAL WOMEN’S DAY👭\n\nToday, we celebrate the strength, courage, and brilliance of every woman who inspires change and shapes the world with resilience and grace. ✨ \n\nLet us honor the voices that lead, the hearts that nurture, and the minds that innovate. \nMay we continue to build a future of equality, respect, and empowerment together. 💜 \n\nWith pride and solidarity, \nCollege Union 2026\n_Government Engineering College Wayanad_ \n\n#WomensDay #EmpowerHer #gecw",
