    "id": "sathva-post-17962596308901175",
    "title": "🌙 *Ahlan – IFTAR PARTY 2026",
    "caption": "🌙 *Ahlan – IFTAR PARTY 2026*\n\n*GECW College Union 2025-26* \nwarmly invites you to an evening of togetherness and harmony.\n\nAs the sun sets and hearts gather, \nlet us come together to break the fast and celebrate the spirit of Ramadan with friendship, gratitude, and unity. 🤍\n\n✨ *Ahlan – Iftar Party* \n📅 *March 09, 2026* \n\nJoin us for a beautiful evening filled with warmth, conversations, and shared moments.",
