    "title": "🌅 *As the sun sets and hearts unite,",
    "caption": "🌅 *As the sun sets and hearts unite,* \nWe gather not just to break the fast, \nbut to strengthen bonds of friendship and unity. 🤍 \n\n✨ *GRAND IFTAR MEET 2026* ✨ \n_College Union – GECW_ \n\nTogether, we share *food, faith, and unforgettable moments.* \n\n🌙 *Coming Soon…*\n\n> For the students, by the students",
