    "title": "🎨 JOIN OUR CREATIVE TEAM! 🎬",
    "caption": "*🎨 JOIN OUR CREATIVE TEAM! 🎬*\n*College Union 2025-26 | GEC Wayanad*\n\nAre you a wizard with pixels or a pro at the timeline? We are looking for talented *Designers & Video Editors* to lead and inspire our creative vision! \n\nJoin an inclusive student union where your creativity knows no boundaries—free from party, caste, or religious discrimination. This is your chance to leave a lasting impact on our campus history.\n\n✨ *Be part of our team!* ✨\n\n🔗 *Apply here:* https://shorturl.at/3GqyD\n\nFor Union updates : \n- whatsapp : chat.whatsapp.com/Gxb387J2R8I9OpIAMpKYwG\n- Instagram: instagram.com/collegeunion.gecw\n\n*ഇനി നമ്മളാണ്, നമ്മുടേതാണ്!* 🚀\n\n> For the students, by the students",
