    "id": "sathva-story-18075991652545121",
    "title": "DETAILS",
    "caption": "DETAILS \n•⁠ ⁠Application Fee: ₹50/-\n•⁠ ⁠Where to get forms: Hostel Section (Office)\n•⁠ ⁠Where to submit: Hostel Section (Office)\n\n REQUIRED DOCUMENTS \n•⁠ ⁠Income Certificate (Valid for 1 year, including the date 08/05/26).\n•⁠ ⁠Previous Semester Grade Card (Attested by Class Advisor).\n•⁠ ⁠Caste Certificate (For SC/ST students).\n•⁠ ⁠Copy of Ration Card (For BPL category students).\n\nNote: Ensure all documents are submitted along with the application form before the deadline.",
