    "id": "sathva-story-17870325261491686",
    "title": "The last date for submitting medical leave is March 27.",
    "caption": "The last date for submitting medical leave is March 27.\nStudents who no longer require medical leave before April 7 are requested to withdraw their application.\nDue to election duty, officers will be on duty.",
    "date": "2026-04-09",
    "category": "events_programs",
