    "title": "Class Rearrangement for S6, S4 & S8 Students",
    "caption": "Class Rearrangement for S6, S4 & S8 Students\nYour classes will be conducted in ONLINE mode starting from March 28, 2026.\nHostel mess  will NOT be available from March 28 to April 17",
    "date": "2026-04-09",
